mapper.select:
SELECT a.asgn_id AS "id",p.proj_id AS "projectId",p.proj_nm AS "projectName",a.job_cd AS "jobCode",
coalesce(j.code_nm,a.job_cd) AS "jobName",a.input_bgn_dt AS "startDate",a.input_end_dt AS "endDate",
a.ctrt_mm::text AS "contractMm",a.asgn_stat_cd AS "assignmentStatus"
FROM tb_pj_asgn a JOIN tb_pj_proj p ON p.proj_id=a.proj_id
LEFT JOIN tb_sy_code j ON j.code_grp_id='JOB' AND j.code=a.job_cd WHERE a.dev_id=#{id}
ORDER BY a.input_bgn_dt DESC,a.asgn_id ASC LIMIT #{size} OFFSET #{offset}
